export interface InvoiceLine {
  0: string; // Product Name
  1: string; // HSN
  2: number; // Quantity
  3: string; // Unit (Mtr, Kg, No, Bag, etc.)
  4: number; // Rate
  5: number; // Amount
}

export interface InvoiceRecord {
  fy: string;
  no: number;
  dt: string;
  c: string;
  gst: string;
  st: string;
  veh: string;
  tx: number;
  cg: number;
  sg: number;
  ig: number;
  gp: number;
  ro: number;
  net: number;
  pre: number;
  bal: number;
  disc: number;
  nar: string;
  w: string;
  a: string[];
  dc: string;
  L: [string, string, number, string, number, number][];
}

export interface CustomerRecord {
  n: string;
  a: string;
  s: string;
  g: string;
  m: string;
}

export interface ProductRecord {
  n: string;
  h: string;
}

export interface ReceiptPaymentRecord {
  fy: string;
  no: number;
  dt: string;
  p: string;
  m: string;
  amt: number;
  nar: string;
}

export interface CompanyInfo {
  n: string;
  a: string;
  ph: string;
  em: string;
  g: string;
  pan: string;
}

export interface BillingDatabase {
  inv: InvoiceRecord[];
  cust: CustomerRecord[];
  prod: ProductRecord[];
  rec: ReceiptPaymentRecord[];
  pay: ReceiptPaymentRecord[];
  co: CompanyInfo;
}

